class Solution {    public int search(int[] nums, int target) {        int low = 0, high = nums.length - 1;        while (low <= high) {            int mid = (low + high) / 2;            if (nums[mid] == target) {                return mid;            }            if (nums[low] <= nums[mid]) {                if (nums[low] <= target && target < nums[mid]) {                    high = mid - 1;                } else {                    low = mid + 1;                }            } else {                if (nums[mid] < target && target <= nums[high]) {                    low = mid + 1;                } else {                    high = mid - 1;                }            }        }        return -1;    }}/*Time and Space Complexity:----------------------------Time Complexity: The time complexity is O(logn) since we're performing a binary search over the elements of the array.Space Complexity: The space complexity is O(1) because we only use a constant amount of space to store our variables (left, right, mid), regardless of the size of the input array.*/